import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const GROUND_SCALE = 1 / Math.cos(THREE.MathUtils.degToRad(55));
const mat = (color, roughness = 0.9) => new THREE.MeshStandardMaterial({ color, roughness });

export class Town3D {
  constructor(canvas, shops, buildings, props) {
    this.canvas = canvas;
    this.renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false, powerPreference: 'high-performance' });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    this.renderer.shadowMap.enabled = false;
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.2;
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color('#a9c8d3');
    this.camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 1, 8000);
    this.camera.rotation.order = 'YXZ';
    this.cameraAngle = THREE.MathUtils.degToRad(55);
    this.root = new THREE.Group();
    this.root.scale.z = GROUND_SCALE;
    this.scene.add(this.root);
    this.dynamic = new THREE.Group();
    this.root.add(this.dynamic);
    this.copMeshes = new Map();
    this.poopMeshes = [];
    this.clock = 0;
    this.addLights();
    this.buildGround();
    this.buildRoads();
    this.buildPark();
    this.buildBuildings(shops, buildings);
    this.buildTrees(props);
    this.buildStreetFurniture();
    this.buildCars();
    this.buildResidents();
    this.dog = this.createDog();
    this.dynamic.add(this.dog);
    this.resize();
    window.addEventListener('resize', () => this.resize());
  }

  addLights() {
    this.scene.add(new THREE.HemisphereLight('#f0f7df', '#68745a', 2.15));
    const sun = new THREE.DirectionalLight('#fff0ce', 3.1);
    sun.position.set(-500, 1400, 800);
    this.scene.add(sun);
  }

  box(parent, x, y, z, w, h, d, material, options = {}) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
    mesh.position.set(x, y + h / 2, z);
    if (options.rotation) mesh.rotation.y = options.rotation;
    parent.add(mesh);
    return mesh;
  }

  cylinder(parent, x, y, z, radiusTop, radiusBottom, height, material, segments = 10) {
    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments), material);
    mesh.position.set(x, y + height / 2, z);
    parent.add(mesh);
    return mesh;
  }

  sphere(parent, x, y, z, sx, sy, sz, material, segments = 10) {
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(1, segments, Math.max(6, segments - 2)), material);
    mesh.position.set(x, y, z);
    mesh.scale.set(sx, sy, sz);
    parent.add(mesh);
    return mesh;
  }

  flat(parent, x, z, rx, rz, color, y = 0.5) {
    const mesh = new THREE.Mesh(new THREE.CircleGeometry(1, 16), mat(color));
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(x, y, z);
    mesh.scale.set(rx, rz, 1);
    parent.add(mesh);
    return mesh;
  }

  addLabel(parent, text, x, y, z, color = '#fff8df', bg = '#413b30') {
    const canvas = document.createElement('canvas');
    canvas.width = 512; canvas.height = 96;
    const c = canvas.getContext('2d');
    c.fillStyle = bg; c.beginPath(); c.roundRect(8, 8, 496, 80, 18); c.fill();
    c.font = 'bold 42px sans-serif'; c.textAlign = 'center'; c.textBaseline = 'middle'; c.fillStyle = color; c.fillText(text, 256, 49, 470);
    const texture = new THREE.CanvasTexture(canvas); texture.colorSpace = THREE.SRGBColorSpace;
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false }));
    sprite.position.set(x, y, z); sprite.scale.set(112, 21, 1); parent.add(sprite); return sprite;
  }

  buildGround() {
    this.box(this.root, 950, -23, 675, 2050, 46, 1510, mat('#a8bb87'));
    const patches = [
      [150, 300, 240, 150, '#afc28f'], [730, 280, 185, 140, '#91ad78'], [1110, 330, 180, 145, '#b9c48e'],
      [1545, 335, 195, 160, '#a0b57f'], [330, 830, 230, 145, '#9eb980'], [1500, 820, 250, 150, '#92ad78'],
      [260, 1150, 200, 125, '#b1c28e'], [1120, 1160, 230, 120, '#9db57d'], [1720, 1180, 220, 130, '#b6c38c']
    ];
    for (const [x,z,w,d,c] of patches) this.box(this.root, x, 0, z, w, 2, d, mat(c));
    // Small stone paving and garden edges make the blocks feel like a lived-in village.
    const paving = mat('#d4c9ad');
    for (const [x,z,w,d] of [[350,430,330,34],[950,430,420,34],[1580,430,370,34],[350,680,360,34],[1570,680,360,34],[365,1005,410,32],[1510,1005,410,32]]) {
      this.box(this.root, x, 1, z, w, 4, d, paving);
    }
  }

  buildRoads() {
    const asphalt = mat('#777c78'), curb = mat('#d6d0bb'), lane = mat('#eee0b9'), sidewalk = mat('#d9d2bd');
    // Main avenues and their slightly raised pavements.
    this.box(this.root, 950, 1, 557, 2050, 8, 225, asphalt);
    for (const x of [515, 1330]) this.box(this.root, x, 1, 675, 155, 8, 1510, asphalt);
    for (const [x,z,w,d] of [[950,438,2050,10],[950,676,2050,10],[436,675,10,1510],[594,675,10,1510],[1251,675,10,1510],[1409,675,10,1510]]) this.box(this.root,x,7,z,w,8,d,curb);
    this.box(this.root, 950, 10, 557, 2050, 1, 5, lane);
    this.box(this.root, 515, 10, 675, 4, 1, 1510, lane);
    this.box(this.root, 1330, 10, 675, 4, 1, 1510, lane);
    // Broken center lines.
    for (let x=35;x<1900;x+=95) this.box(this.root,x,10,557,46,1,3,lane);
    for (const x of [515,1330]) for(let z=28;z<1330;z+=95)this.box(this.root,x,10,z,3,1,42,lane);
    // Painted zebra crossings at the village intersections.
    for(const x of [515,1330]) for(let i=-4;i<=4;i++) this.box(this.root,x+i*13,11,490,7,1,36,mat('#f2ead5'));
    for(const z of [557]) for(const y of [0]) void(z,y);
    // Parking bays along the market street.
    for(const x of [220,287,760,827,1495,1562,1730]) {
      this.box(this.root,x,10,466,2,1,42,mat('#efdfb9'));
      this.box(this.root,x+55,10,466,2,1,42,mat('#efdfb9'));
    }
    this.box(this.root, 950, 8, 458, 2050, 3, 26, sidewalk);
    this.box(this.root, 950, 8, 656, 2050, 3, 26, sidewalk);
  }

  buildPark() {
    const grass=mat('#8fb47b'), path=mat('#d7c89e'), water=mat('#79b8b8');
    this.box(this.root, 990, 1, 850, 390, 9, 300, grass);
    this.box(this.root, 990, 7, 835, 315, 4, 34, path);
    this.box(this.root, 990, 7, 875, 42, 4, 220, path);
    this.box(this.root, 1085, 7, 850, 100, 4, 76, path);
    // Little fountain and circular plaza.
    const plaza = new THREE.Mesh(new THREE.CylinderGeometry(43,43,5,24), mat('#d9cfb8'));
    plaza.position.set(1090,7,920); this.root.add(plaza);
    const basin = new THREE.Mesh(new THREE.CylinderGeometry(27,30,12,24), mat('#9caa9a'));
    basin.position.set(1090,15,920); this.root.add(basin);
    const pool = new THREE.Mesh(new THREE.CylinderGeometry(22,22,2,24), water); pool.position.set(1090,22,920); this.root.add(pool);
    this.cylinder(this.root,1090,23,920,4,7,25,mat('#d5c7a6'),12);
    this.sphere(this.root,1090,51,920,7,7,7,water,12);
    // Small playground and a flower bed.
    this.box(this.root, 875, 7, 930, 56, 7, 34, mat('#d88d62'));
    this.box(this.root, 848, 10, 930, 5, 30, 5, mat('#6a7255'));
    this.box(this.root, 902, 10, 930, 5, 30, 5, mat('#6a7255'));
    this.box(this.root, 1020, 7, 963, 74, 4, 23, mat('#627d54'));
    for(let i=0;i<8;i++) this.sphere(this.root,990+i*9,13,963,4,5,4,mat(['#e58b71','#e8c86d','#d5a5cc'][i%3]),7);
    this.addBench(875,790,0); this.addBench(1140,804,Math.PI/2); this.addBench(930,962,0);
  }

buildBuildings(shops, buildings) {
  const walls=['#e8d9b8','#d8cbb1','#e9c8a9','#c9d6c1','#e5d7c2','#d2c8b7'];
  const roofs=['#a45f49','#8b6a51','#b47a56','#716e63','#995b4c'];
  const windowGlass=mat('#86aeb0'), trim=mat('#f2e7d2'), dark=mat('#574b3e');
  const shopByPosition=new Map(shops.map(s=>[`${s.x},${s.y}`,s]));
  for (let i=0;i<buildings.length;i++) {
    const b=buildings[i], shop=shopByPosition.get(`${b.x},${b.y}`);
    const group=new THREE.Group(); group.position.set(b.x,0,b.y); this.root.add(group);
    const wall=mat(shop?.color || walls[i%walls.length]);
    const depth=b.h, width=b.w, height=shop?82:78+(i%3)*15;
    this.box(group,0,0,0,width,height,depth,wall);
    // Foundation, corner stones and roof silhouette.
    this.box(group,0,0,depth/2+2,width+8,12,8,mat('#c7b99d'));
    if(shop){
      this.box(group,0,height,0,width+22,13,depth+22,mat('#776d5d'));
      this.box(group,0,height+9,0,width+12,9,depth+12,mat(shop.color));
      // Recessed shopfront, glazed windows, timber framing and striped canopy.
      this.box(group,0,20,depth/2+4,width-26,53,5,mat('#665646'));
      this.box(group,0,23,depth/2+7,width-36,45,2,windowGlass);
      this.box(group,0,0,depth/2+12,38,53,16,mat('#7a503c'));
      this.box(group,0,27,depth/2+21,2,48,2,mat('#d7ba88'));
      this.box(group,0,73,depth/2+1,width-14,4,8,mat('#f3e5c7'));
      this.box(group,0,86,depth/2+14,width+9,6,26,mat('#fff0ce'));
      this.addLabel(group,shop.name,0,91,depth/2+29,'#fff6df',shop.color);
      for(let x=-width/2+10;x<width/2;x+=19){
        this.box(group,x,58,depth/2+14,18,3,26,mat((Math.floor((x+width/2)/19)%2)?'#f2e0bd':'#d87659'));
      }
      this.box(group,-width/2+13,35,depth/2+11,4,43,5,trim);
      this.box(group,width/2-13,35,depth/2+11,4,43,5,trim);
      // A little side wall sign and rooftop air-conditioning unit.
      this.box(group,width/2+3,45,0,9,26,26,mat('#e2d4b8'));
      this.box(group,width/2-20,height+19,-depth/2+20,28,12,24,mat('#8d9288'));
    } else {
      // Gable-front cottages, with plaster, timber trim, doors and deep-set windows.
      const roofMat=mat(roofs[i%roofs.length]);
      this.box(group,0,height/2,depth/2+2,width-20,height-18,5,mat('#f3e7d0'));
      const doorX=(i%2? -width*.24: width*.24);
      this.box(group,doorX,0,depth/2+6,25,48,8,mat('#815840'));
      this.sphere(group,doorX+7,25,depth/2+11,1.5,1.5,1.5,mat('#e9c66e'),8);
      for(const wx of [-width*.25,width*.25]) if(Math.abs(wx-doorX)>22){
        this.box(group,wx,35,depth/2+6,35,28,8,windowGlass);
        this.box(group,wx,35,depth/2+11,4,31,3,trim);
        this.box(group,wx,35,depth/2+11,39,4,3,trim);
        this.box(group,wx,50,depth/2+8,42,5,13,trim);
      }
      // Hipped red-tile roof with ridge cap and chimney.
      const roof=new THREE.Mesh(new THREE.ConeGeometry(Math.max(width,depth)*.69,38,4),roofMat);
      roof.position.set(0,height+18,0); roof.rotation.y=Math.PI/4; group.add(roof);
      this.box(group,width*.27,height+48,-depth*.12,13,36,15,mat('#9a5945'));
      this.box(group,0,12,depth/2+7,width-9,6,9,mat('#d0b894'));
      if(i%3===0){
        this.box(group,0,height+4,depth/2+3,width-14,9,8,mat('#584a3d'));
        this.addLabel(group,['CASA','LA PLAZA','CASA RURAL','PAN Y MÁS'][i%4],0,height+12,depth/2+9,'#fff5dc','#715c49');
      }
    }
    // Side windows bring out depth from the elevated camera.
    for(const sign of [-1,1]){
      this.box(group,sign*(width/2+3),35,-depth*.18,5,26,31,windowGlass);
      this.box(group,sign*(width/2+6),35,-depth*.18,3,30,4,trim);
    }
  }
  // Distinctive little church tower anchors the village skyline.
  this.buildChurch(1035,176);
  // Tío Paco's outdoor flea-market stall and the dog wash station.
  this.buildMarketStall(); this.buildWashStation();
}

