buildTrees(props) {
  const greens=['#557d50','#668a55','#79975c','#4f7550','#8ca467'];
  const skip=(x,y)=> buildings.some(b=>x>b.x-35&&x<b.x+b.w+35&&y>b.y-35&&y<b.y+b.h+35) || (y>445&&y<670) || (x>790&&x<1190&&y>700&&y<1000);
  const candidates=props.filter(p=>!skip(p.x,p.y));
  // Top up with a few gardens and roadside trees so the street feels inhabited.
  for(let i=0;i<18;i++){
    const x=42+(i*311)%1815, y=145+(i*197)%1160;
    if(!skip(x,y)) candidates.push({x,y,r:12+(i%4)*2,type:i%greens.length});
  }
  for(const p of candidates){
    const g=new THREE.Group();g.position.set(p.x,0,p.y);this.root.add(g);
    this.flat(g,0,0,p.r*1.25,p.r*.7,'#6e735c',1);
    this.cylinder(g,0,1,0,4,6,24,mat('#77583e'),7);
    this.sphere(g,-p.r*.35,36,0,p.r*.78,p.r*.64,p.r*.72,mat(greens[p.type%greens.length]),9);
    this.sphere(g,p.r*.35,39,-p.r*.12,p.r*.72,p.r*.68,p.r*.75,mat(greens[(p.type+1)%greens.length]),9);
    this.sphere(g,0,50,0,p.r*.64,p.r*.63,p.r*.67,mat(greens[(p.type+2)%greens.length]),9);
  }
  // Planter boxes along the paseo, plus flower dots.
  for(const [x,z] of [[250,427],[440,685],[790,425],[1170,684],[1500,428],[1680,685],[750,1005],[1300,1007]]){
    this.box(this.root,x,5,z,76,11,24,mat('#8b7257'));
    this.box(this.root,x,16,z,67,12,18,mat('#78965e'));
    for(let i=0;i<5;i++)this.sphere(this.root,x-26+i*13,28,z,4,4,4,mat(i%2?'#e1a6a4':'#e5cb72'),7);
  }
}

