makePerson(shirt, trousers, hair, variant=0) {
  const g=new THREE.Group();
  this.cylinder(g,0,10,0,8,9,24,mat(trousers),8);
  this.sphere(g,0,40,0,9,13,8,mat(shirt),9);
  this.sphere(g,0,59,0,8,9,8,mat('#c99370'),9);
  this.sphere(g,0,66,0,8,4,8,mat(hair),8);
  for(const sx of [-4,4])this.sphere(g,sx,60,7,1,1.3,1,mat('#37352f'),6);
  for(const sx of [-4,4]){
    const arm=this.cylinder(g,sx*1.6,22,0,3,3,18,mat(shirt),7);arm.rotation.z=sx<0?-.3:.3;
    this.box(g,sx,0,0,6,10,7,mat(trousers));
  }
  if(variant%4===0)this.sphere(g,0,53,-9,2,2,2,mat('#c5a95f'),7);
