  const tail=this.cylinder(g,-23,18,0,2.5,3.2,22,coat,8);tail.rotation.z=-.75;g.userData.tail=tail;
  const collar=this.cylinder(g,8,21,0,1.7,1.7,24,mat('#df7959'),10);collar.rotation.z=Math.PI/2;
  this.sphere(g,17,22,0,2.7,3.5,2.5,mat('#e6c46e'),8);
