makeStreetLife() {
  for(const [x,z,r] of [[880,810,0],[1140,900,Math.PI/2],[350,480,0],[1520,480,Math.PI/2],[480,690,0],[690,965,Math.PI/2],[1200,820,0]])this.bench(x,z,r);
